/* ============================================================
   أطياب الجاسم (React) — عرض العطور (2DPerfumeView)

   ★ هذا المكوّن منقول عن مشهد العرض الأصلي في الملف المرجعي
     (atyab-aljasem-standalone.html · قسم «العطور»): نفس الأرقام
     والهندسة والمواد والإضاءة والحلقة الزمنية، مع إعادة كتابته على
     واجهة three.js العامة بدل الأسماء المختصرة داخل حزمة الأصل.

   المشهد:
     · طبق معدني دوّار (Cylinder + Circle + Torus) مع علامات ذهبية.
     · قاعدة كروم أسطوانية بثلاث حلقات ذهبية وهالة دافئة.
     · أربع عبوات (قصاصات PNG شفافة) موزّعة على دائرة، تدور خطوةً
       كل stepMs مع تسارع/تباطؤ (easeInOut)، وكل عبوة:
       ظلّ تلامس، انعكاس على الطبق، سطوع وشفافية حسب مواجهتها.
     · الكاميرا تُضبط تلقائياً (بحث ثنائي + تصحيح رأسي) لتضمّ المشهد
       كاملاً بحسب مقاس الإطار ونسبة الأبعاد.
     · ظِلّ/ضوء بيئي من خريطة متساوية مستطيل مرسومة على canvas (PMREM).
     · parallax خفيف يتبع المؤشر على الأجهزة ذات المؤشّر الدقيق.
     · عنوانان أسفل المشهد: لاتيني + عربي (caption) يتبدّلان مع العبوة.

   ★ الأداء: لا حالة React داخل الحلقة — كل شيء في مراجع three.js،
     والحلقة تتوقّف عند خروج القسم من الشاشة وعند إخفاء التبويب.
   ★ الأصول: public/home/hero-*.webp (قصاصات العبوات الأربع الجديدةة — شفافة بدون خلفية).
   ============================================================ */

import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";

/* ثوابت المشهد — منقولة حرفياً من HERSH_CONFIG في الملف المرجعي */
export const STAGE_CONFIG = {
  stepMs: 1000,
  spinRatio: 0.6,
  bottleHeight: 1,
  bottleRadius: 0.6,
  platterRadius: 1.1,
  platterDepth: 0.1,
  platformHeight: 0.12,
  platformRadius: 0.37,
  elevationDeg: 19,
  fov: 30,
  parallax: true,
  showCaption: true,
  background: "transparent",
  reflection: 0.52
};

/* العبوات الجديدةة — نسخ 480w المضغوطة (كانت 800px/25-50KB لكل عبوة).
   تُرسم على canvas بحجم ~300px، فـ480px كافية وتوفّر ~60KB. */
export const STAGE_PRODUCTS = [
  { latin: "ATHAR", arabic: "أثار", img: "home/hero-athar-480.webp" },
  { latin: "AURA", arabic: "أورا", img: "home/hero-aura-480.webp" },
  { latin: "RIQAH", arabic: "رِقاح", img: "home/hero-riqah-480.webp" },
  { latin: "VESTIGE", arabic: "فيستيج", img: "home/hero-vestige-480.webp" }
];

const clamp01 = function (v) {
  return Math.min(1, Math.max(0, v));
};

const smoothstep = function (a, b, t) {
  const x = clamp01((t - a) / (b - a));
  return x * x * (3 - 2 * x);
};

const easeInOutCubic = function (s) {
  return s < 0.5 ? 4 * s * s * s : 1 - Math.pow(-2 * s + 2, 3) / 2;
};

function loadImage(src) {
  return new Promise(function (resolve, reject) {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = function () {
      resolve(img);
    };
    img.onerror = function () {
      reject(new Error("failed to load " + src));
    };
    img.src = src;
  });
}

/* نسيج من canvas بنفس مقاس اللوحة (hd في الأصل) */
function canvasTexture(size, draw) {
  const c = document.createElement("canvas");
  c.width = size;
  c.height = size;
  const ctx = c.getContext("2d");
  draw(ctx, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

/* خريطة بيئة متساوية مستطيلة (tw في الأصل) */
function environmentTexture(renderer) {
  const c = document.createElement("canvas");
  c.width = 512;
  c.height = 256;
  const ctx = c.getContext("2d");
  const g = ctx.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, "#9aa3b4");
  g.addColorStop(0.42, "#454c5c");
  g.addColorStop(0.52, "#101319");
  g.addColorStop(1, "#040507");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 512, 256);
  const blob = function (x, y, r, a) {
    const rg = ctx.createRadialGradient(x, y, 0, x, y, r);
    rg.addColorStop(0, "rgba(255,255,255," + a + ")");
    rg.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = rg;
    ctx.fillRect(0, 0, 512, 256);
  };
  blob(150, 64, 120, 0.55);
  blob(370, 48, 90, 0.4);
  blob(280, 140, 200, 0.12);

  const tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  const pmrem = new THREE.PMREMGenerator(renderer);
  const env = pmrem.fromEquirectangular(tex).texture;
  pmrem.dispose();
  tex.dispose();
  return env;
}

/* نسيج انعكاس العبوة على الطبق (aw في الأصل): قلب رأسي + تمويه + تلاشٍ تدريجي */
function reflectionTexture(img) {
  const w = img.naturalWidth;
  const h = img.naturalHeight;
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const ctx = c.getContext("2d");
  ctx.translate(0, h);
  ctx.scale(1, -1);
  try {
    ctx.filter = "blur(2.5px)";
  } catch (e) {
    /* متصفّح بلا filter — نتجاهل */
  }
  ctx.drawImage(img, 0, 0);
  try {
    ctx.filter = "none";
  } catch (e) {
    /* تجاهل */
  }
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalCompositeOperation = "destination-in";
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, "rgba(0,0,0,0.95)");
  g.addColorStop(0.42, "rgba(0,0,0,0.5)");
  g.addColorStop(0.78, "rgba(0,0,0,0.12)");
  g.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function prefersReducedMotion() {
  try {
    return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  } catch (e) {
    return false;
  }
}

export default function PerfumeView2D(props) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const loadingRef = useRef(null);
  const captionRef = useRef(null);
  const latinRef = useRef(null);
  const arabicRef = useRef(null);
  const apiRef = useRef(null);

  /* ★ مدخلات المشهد مثبتة الهوية: إعادة البناء فقط عند تغيّرها فعلياً
     (كائن cfg الطازج كل رسم كان سيعيد تشغيل الـeffect بلا داعٍ). */
  const propsItems = props && props.items;
  const propsConfig = props && props.config;
  const items = propsItems || STAGE_PRODUCTS;
  const cfg = useMemo(function () {
    return Object.assign({}, STAGE_CONFIG, propsConfig || {});
  }, [propsConfig]);
  const onPick = props && props.onPick;

  const isActive = !props || props.active !== false;
  useEffect(
    function () {
      if (!isActive) return undefined;
      const wrapEl = wrapRef.current;
      const canvasEl = canvasRef.current;
      if (!wrapEl || !canvasEl) return undefined;

      const products = (items || []).filter(function (p) {
        return p && p.img;
      });
      if (!products.length) return undefined;

      const C = cfg;
      const count = products.length;
      const stepAngle = (Math.PI * 2) / count;

      /* ---------- المُصيّر والمشهد والكاميرا ---------- */
      const renderer = new THREE.WebGLRenderer({
        canvas: canvasEl,
        antialias: true,
        alpha: true,
        preserveDrawingBuffer: true
      });
      if (!renderer.capabilities || !renderer.capabilities.isWebGL2) {
        /* WebGL1 يعمل أيضاً — لا شيء مطلوب */
      }
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.outputColorSpace = THREE.SRGBColorSpace;

      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(C.fov, 1, 0.1, 60);
      const parallaxGroup = new THREE.Group();
      parallaxGroup.add(camera);
      scene.add(parallaxGroup);
      const cameraTarget = new THREE.Vector3(0, 0.5, 0);

      scene.environment = environmentTexture(renderer);

      /* ---------- الإضاءة ---------- */
      const key = new THREE.DirectionalLight(16773853, 1.35);
      key.position.set(2.4, 4.2, 3.4);
      scene.add(key);
      const fill = new THREE.DirectionalLight(10466520, 0.5);
      fill.position.set(-3.2, 1.6, 1.8);
      scene.add(fill);
      const rimA = new THREE.DirectionalLight(11125488, 0.42);
      rimA.position.set(-1.4, 2.8, -3.6);
      scene.add(rimA);
      const rimB = new THREE.DirectionalLight(16767404, 0.3);
      rimB.position.set(2.2, 1.8, -3.2);
      scene.add(rimB);
      const spot = new THREE.SpotLight(16766880, 22, 9, Math.PI / 5, 0.7, 1.6);
      spot.position.set(0, 4.4, 0.9);
      spot.target.position.set(0, 0, 0.5);
      scene.add(spot);
      scene.add(spot.target);

      /* ---------- المواد المشتركة ---------- */
      const goldMat = new THREE.MeshStandardMaterial({ color: 13280872, metalness: 1, roughness: 0.3 });
      const rimMat = new THREE.MeshStandardMaterial({ color: 856086, metalness: 0.5, roughness: 0.22 });

      const disposables = [renderer];

      /* ---------- الطبق ---------- */
      const platter = new THREE.Group();
      scene.add(platter);

      const platterBase = new THREE.Mesh(
        new THREE.CylinderGeometry(C.platterRadius, C.platterRadius * 1.012, C.platterDepth, 96, 1),
        rimMat
      );
      platterBase.position.y = -C.platterDepth / 2;
      platter.add(platterBase);

      const platterTop = new THREE.Mesh(
        new THREE.CircleGeometry(C.platterRadius, 96),
        new THREE.MeshStandardMaterial({ color: 1448741, metalness: 0.72, roughness: 0.13 })
      );
      platterTop.rotation.x = -Math.PI / 2;
      platterTop.position.y = 0.001;
      platter.add(platterTop);

      const platterRing = new THREE.Mesh(new THREE.TorusGeometry(C.platterRadius * 0.988, 0.011, 12, 160), goldMat);
      platterRing.rotation.x = Math.PI / 2;
      platterRing.position.y = 0.002;
      platter.add(platterRing);

      const contactShadowTex = canvasTexture(128, function (ctx, w, h) {
        const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
        g.addColorStop(0, "rgba(0,0,0,0.55)");
        g.addColorStop(0.55, "rgba(0,0,0,0.22)");
        g.addColorStop(1, "rgba(0,0,0,0)");
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, w, h);
      });

      for (let i = 0; i < count; i++) {
        const a = i * stepAngle;
        const tick = new THREE.Mesh(new THREE.BoxGeometry(0.005, 0.0015, 0.2), goldMat);
        tick.position.set(Math.sin(a) * C.platterRadius * 0.8, 0.0022, Math.cos(a) * C.platterRadius * 0.8);
        tick.rotation.y = a;
        platter.add(tick);

        const contact = new THREE.Mesh(
          new THREE.CircleGeometry(0.24, 48),
          new THREE.MeshBasicMaterial({ map: contactShadowTex, transparent: true, depthWrite: false })
        );
        contact.rotation.x = -Math.PI / 2;
        contact.position.set(Math.sin(a) * C.bottleRadius, 0.0035, Math.cos(a) * C.bottleRadius);
        platter.add(contact);
      }

      /* ---------- القاعدة (المنصّة) ---------- */
      const platform = new THREE.Group();
      platform.position.set(0, 0, C.bottleRadius);
      scene.add(platform);

      const ph = C.platformHeight;
      const pr = C.platformRadius;
      const chromeMat = new THREE.MeshStandardMaterial({ color: 658707, metalness: 0.92, roughness: 0.2, envMapIntensity: 1.25 });
      const chromeTopMat = new THREE.MeshStandardMaterial({ color: 3293013, metalness: 0.78, roughness: 0.07, envMapIntensity: 1.4 });

      const platformBase = new THREE.Mesh(new THREE.CylinderGeometry(pr * 1.18, pr * 1.24, ph * 0.28, 72, 1), [
        chromeMat,
        chromeMat,
        chromeMat
      ]);
      platformBase.position.y = ph * 0.14;
      platform.add(platformBase);

      const platformBody = new THREE.Mesh(new THREE.CylinderGeometry(pr, pr * 1.06, ph * 0.72, 72, 1), [
        chromeMat,
        chromeTopMat,
        chromeMat
      ]);
      platformBody.position.y = ph * 0.64;
      platform.add(platformBody);

      const platformTopRing = new THREE.Mesh(new THREE.TorusGeometry(pr * 1.005, 0.009, 12, 120), goldMat);
      platformTopRing.rotation.x = Math.PI / 2;
      platformTopRing.position.y = ph * 0.98;
      platform.add(platformTopRing);

      const platformGlow = new THREE.Mesh(
        new THREE.RingGeometry(pr * 1.34, pr * 1.52, 96),
        new THREE.MeshBasicMaterial({
          color: 16767392,
          transparent: true,
          opacity: 0.28,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
          toneMapped: false
        })
      );
      platformGlow.rotation.x = -Math.PI / 2;
      platformGlow.position.y = 0.003;
      platform.add(platformGlow);

      const platformMidRing = new THREE.Mesh(new THREE.TorusGeometry(pr * 1.18, 0.007, 10, 120), goldMat);
      platformMidRing.rotation.x = Math.PI / 2;
      platformMidRing.position.y = ph * 0.27;
      platform.add(platformMidRing);

      const poolGlow = new THREE.Mesh(
        new THREE.CircleGeometry(C.platformRadius * 1.9, 64),
        new THREE.MeshBasicMaterial({
          map: canvasTexture(256, function (ctx, w, h) {
            const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
            g.addColorStop(0, "rgba(255,226,176,0.62)");
            g.addColorStop(0.4, "rgba(255,208,146,0.22)");
            g.addColorStop(1, "rgba(255,200,130,0)");
            ctx.fillStyle = g;
            ctx.fillRect(0, 0, w, h);
          }),
          transparent: true,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
          toneMapped: false
        })
      );
      poolGlow.rotation.x = -Math.PI / 2;
      poolGlow.position.y = C.platformHeight + 0.0015;
      platform.add(poolGlow);

      /* ---------- المقاسات المتجاوبة ---------- */
      const live = { bottle: C.bottleRadius, platter: C.platterRadius, platform: C.platformRadius };

      function applyResponsiveScale() {
        const ar = (window.innerWidth || 1) / Math.max(1, window.innerHeight || 1);
        const e = ar < 1 ? 0.84 : ar < 1.35 ? 0.93 : 1;
        live.bottle = C.bottleRadius * e;
        live.platter = C.platterRadius * e;
        live.platform = C.platformRadius * e;
        const ts = live.platter / C.platterRadius;
        const ns = live.platform / C.platformRadius;
        platter.scale.set(ts, 1, ts);
        platform.scale.set(ns, 1, ns);
        platform.position.z = live.bottle;
      }

      /* ---------- ضبط الكاميرا لاحتواء المشهد ---------- */
      function stageAspect() {
        return Math.max(1e-4, wrapEl.clientWidth / Math.max(1, wrapEl.clientHeight));
      }

      function fitCamera() {
        const aspect = stageAspect();
        camera.aspect = aspect;
        const top = C.bottleHeight + C.platformHeight;
        const spacing = live.platform + 0.025;
        const points = [];
        const ring = function (r, y, n, cx, cz) {
          const ox = cx || 0;
          const oz = cz || 0;
          for (let i = 0; i < n; i++) {
            const a = (i / n) * Math.PI * 2;
            points.push(new THREE.Vector3(ox + Math.sin(a) * r, y, oz + Math.cos(a) * r));
          }
        };
        ring(live.platter, 0, 72, 0, 0);
        ring(live.platter, -C.platterDepth, 72, 0, 0);
        ring(live.bottle, 0, 72, 0, 0);
        ring(live.bottle, top, 72, 0, 0);
        ring(spacing, C.platformHeight, 48, 0, live.bottle);

        const tanHalf = Math.tan((C.fov / 2) * (Math.PI / 180));
        const tanWide = tanHalf * aspect;
        const elev = C.elevationDeg * (Math.PI / 180);
        const dir = new THREE.Vector3(0, Math.sin(elev), Math.cos(elev)).normalize();
        const target = new THREE.Vector3(0, top * 0.5, 0);
        const inv = new THREE.Matrix4();
        const v = new THREE.Vector3();

        const fits = function (d) {
          camera.position.copy(target).addScaledVector(dir, d);
          camera.lookAt(target);
          camera.updateMatrixWorld(true);
          inv.copy(camera.matrixWorld).invert();
          for (let i = 0; i < points.length; i++) {
            v.copy(points[i]).applyMatrix4(inv);
            const z = -v.z;
            if (z <= 0.01 || Math.abs(v.x) > z * tanWide * 0.9 || Math.abs(v.y) > z * tanHalf * 0.9) return false;
          }
          return true;
        };

        const solve = function () {
          let lo = 1;
          let hi = 40;
          if (!fits(hi)) hi = 90;
          for (let i = 0; i < 44; i++) {
            const mid = (lo + hi) / 2;
            if (fits(mid)) hi = mid;
            else lo = mid;
          }
          return hi;
        };

        let d = solve();
        for (let i = 0; i < 5; i++) {
          camera.position.copy(target).addScaledVector(dir, d);
          camera.lookAt(target);
          camera.updateMatrixWorld(true);
          inv.copy(camera.matrixWorld).invert();
          let min = Infinity;
          let max = -Infinity;
          for (let k = 0; k < points.length; k++) {
            v.copy(points[k]).applyMatrix4(inv);
            const y = v.y / (-v.z * tanHalf);
            if (y < min) min = y;
            if (y > max) max = y;
          }
          const err = (min + max) / 2;
          if (Math.abs(err) < 0.01) break;
          target.y += err * d * tanHalf;
          d = solve();
        }
        camera.position.copy(target).addScaledVector(dir, d);
        camera.lookAt(target);
        camera.updateMatrixWorld(true);
        camera.updateProjectionMatrix();
        cameraTarget.copy(target);
      }

      /* ---------- العبوات ---------- */
      const bottles = [];
      const reflectionLayer = new THREE.Group();
      reflectionLayer.renderOrder = 8;
      scene.add(reflectionLayer);

      async function buildBottles() {
        const images = await Promise.all(
          products.map(function (p) {
            return loadImage(p.img);
          })
        );
        const height = C.bottleHeight;

        products.forEach(function (product, i) {
          const img = images[i];
          const ratio = img.naturalWidth / img.naturalHeight;
          const w = height * ratio;

          const slot = new THREE.Group();
          scene.add(slot);
          const body = new THREE.Group();
          slot.add(body);

          const map = new THREE.CanvasTexture(img);
          map.colorSpace = THREE.SRGBColorSpace;
          map.anisotropy = 4;
          const quad = new THREE.Mesh(
            new THREE.PlaneGeometry(w, height),
            new THREE.MeshBasicMaterial({
              map: map,
              transparent: true,
              depthWrite: true,
              alphaTest: 0.02,
              toneMapped: false
            })
          );
          quad.position.y = height / 2 - 0.002;
          body.add(quad);

          const contact = new THREE.Mesh(
            new THREE.PlaneGeometry(0.3, 0.17),
            new THREE.MeshBasicMaterial({ map: contactShadowTex, transparent: true, depthWrite: false, toneMapped: false })
          );
          contact.rotation.x = -Math.PI / 2;
          contact.position.set(-0.02, 0.004, -0.012);
          body.add(contact);

          const reflH = height * C.reflection;
          const refl = new THREE.Mesh(
            new THREE.PlaneGeometry(w * C.reflection, reflH),
            new THREE.MeshBasicMaterial({
              map: reflectionTexture(img),
              transparent: true,
              depthWrite: false,
              depthTest: false,
              opacity: 0.5,
              toneMapped: false
            })
          );
          refl.position.y = -reflH / 2;
          const reflHolder = new THREE.Group();
          reflHolder.add(refl);
          reflectionLayer.add(reflHolder);

          bottles.push({
            product: product,
            slot: slot,
            body: body,
            quad: quad,
            contact: contact,
            reflHolder: reflHolder,
            height: height,
            width: w
          });
        });

        fitCamera();
        applyPhase(0);
        renderer.render(scene, camera);
      }

      /* ---------- وضع العبوات عند درجة دوران معيّنة ---------- */
      function applyPhase(step) {
        platter.rotation.y = -step * stepAngle;
        for (let i = 0; i < count; i++) {
          const b = bottles[i];
          if (!b) continue;
          const a = (i - step) * stepAngle;
          const x = Math.sin(a) * live.bottle;
          const z = Math.cos(a) * live.bottle;
          const face = 0.5 + 0.5 * Math.cos(a);
          const front = Math.pow(face, 1.4);
          const dist = Math.hypot(x, z - live.bottle);
          const lift = ph * smoothstep(live.platform * 1.05, live.platform * 0.45, dist);
          const hAngle = Math.acos(Math.max(-1, Math.min(1, Math.cos(a))));
          const vis = 1 - smoothstep(2.55, 3, hAngle);

          b.slot.position.set(x, 0, z);
          b.body.position.y = lift;
          b.body.scale.setScalar(1 + 0.035 * front);
          b.body.visible = vis > 0.02;
          b.quad.material.color.setScalar(0.6 + 0.4 * front);
          b.quad.material.opacity = (0.7 + 0.3 * front) * vis;
          b.contact.material.opacity = (0.34 + 0.5 * (1 - face)) * vis;
          b.contact.scale.setScalar(1 + 0.55 * (1 - face) + 0.08 * front);
          b.reflHolder.position.set(x, 0.004, z);
          b.reflHolder.visible = front > 0.06 && vis > 0.02 && lift < ph * 0.25;
          b.reflHolder.scale.setScalar(1 + 0.03 * front);
          if (b.reflHolder.children[0]) {
            b.reflHolder.children[0].material.opacity = (0.1 + 0.26 * front) * vis;
          }
        }
      }

      /* ---------- العنوانان ---------- */
      const captionCtn = captionRef.current;
      let captionShown = -1;
      let captionTimer = 0;

      function setCaption(index) {
        const i = count ? ((Math.round(index) % count) + count) % count : 0;
        if (i === captionShown) return;
        captionShown = i;
        const product = products[i];
        if (!product) return;
        if (!captionCtn || !C.showCaption) return;
        captionCtn.classList.add("swap");
        window.clearTimeout(captionTimer);
        captionTimer = window.setTimeout(function () {
          if (latinRef.current) latinRef.current.textContent = product.latin || "";
          if (arabicRef.current) arabicRef.current.textContent = product.arabic || "";
          captionCtn.classList.remove("swap");
        }, 300);
      }

      /* ---------- المؤشّر (parallax) ---------- */
      const mouse = { x: 0, y: 0 };
      const smooth = { x: 0, y: 0 };
      const finePointer = typeof window.matchMedia === "function" ? window.matchMedia("(pointer: fine)").matches : true;
      const onPointerMove = function (e) {
        const w = window.innerWidth || 1;
        const h = window.innerHeight || 1;
        mouse.x = (e.clientX / w) * 2 - 1;
        mouse.y = (e.clientY / h) * 2 - 1;
      };
      if (C.parallax && finePointer) window.addEventListener("pointermove", onPointerMove, { passive: true });

      /* ---------- الحلقة ---------- */
      const reduced = prefersReducedMotion();
      let paused = false;
      let hiddenAt = 0;
      let startTime = performance.now();
      let raf = 0;
      let last = 0;

      function frame(now) {
        raf = window.requestAnimationFrame(frame);
        if (paused) return;
        const elapsed = Math.max(0, now - startTime);
        const step = Math.max(120, C.stepMs);
        const spinDur = step * (1 - Math.min(0.95, Math.max(0, C.spinRatio)));
        const hold = step - spinDur;
        let idx = Math.floor(elapsed / step);
        if (!Number.isFinite(idx) || idx < 0) idx = 0;
        const phase = (elapsed - idx * step - hold) / Math.max(1, spinDur);
        const e = easeInOutCubic(clamp01(phase));
        if (e > 0.82) setCaption((idx + 1) % count);
        else setCaption(idx % count);
        applyPhase(idx + e);
        if (C.parallax && finePointer) {
          smooth.x += (mouse.x - smooth.x) * 0.04;
          smooth.y += (mouse.y - smooth.y) * 0.04;
          parallaxGroup.rotation.y = -smooth.x * 0.075;
          parallaxGroup.rotation.x = smooth.y * 0.03;
        }
        renderer.render(scene, camera);
        last = now;
      }
      void last;

      function onVisibility() {
        if (document.hidden) {
          if (!paused) {
            paused = true;
            hiddenAt = performance.now();
          }
        } else if (paused) {
          startTime += performance.now() - hiddenAt;
          paused = false;
        }
      }
      document.addEventListener("visibilitychange", onVisibility);

      /* ---------- المقاس ---------- */
      function resize() {
        const w = wrapEl.clientWidth;
        const h = wrapEl.clientHeight;
        if (!w || !h) return;
        applyResponsiveScale();
        renderer.setSize(w, h, false);
        fitCamera();
      }

      let resizeTimer = 0;
      let ro = null;
      if (window.ResizeObserver) {
        ro = new ResizeObserver(function () {
          window.clearTimeout(resizeTimer);
          resizeTimer = window.setTimeout(resize, 60);
        });
        ro.observe(wrapEl);
      } else {
        window.addEventListener("resize", resize);
      }
      const onOrient = function () {
        window.setTimeout(resize, 220);
      };
      window.addEventListener("orientationchange", onOrient);

      /* ---------- التوقّف عند خروج القسم من الشاشة ---------- */
      function inView() {
        if (wrapEl.closest("[hidden]")) return false;
        const r = wrapEl.getBoundingClientRect();
        const h = window.innerHeight || 800;
        return r.width > 0 && r.height > 0 && r.top < h + 160 && r.bottom > -160;
      }
      function sync() {
        if (inView()) {
          if (paused) {
            startTime += performance.now() - hiddenAt;
            paused = false;
          }
        } else if (!paused) {
          paused = true;
          hiddenAt = performance.now();
        }
      }
      let io = null;
      if ("IntersectionObserver" in window) {
        io = new IntersectionObserver(
          function () {
            sync();
          },
          { rootMargin: "160px" }
        );
        io.observe(wrapEl);
      }
      window.addEventListener("scroll", sync, { passive: true, capture: true });
      window.addEventListener("resize", sync, { passive: true });
      sync();

      /* ---------- واجهة برمجية بسيطة (كما في الأصل) ---------- */
      apiRef.current = {
        config: C,
        products: products,
        next: function () {
          startTime -= Math.max(120, C.stepMs);
        },
        setPhase: function (p) {
          paused = true;
          applyPhase(p);
          setCaption(p);
          renderer.render(scene, camera);
        },
        resumeFrom: function () {
          startTime = performance.now();
          paused = false;
        },
        three: { scene: scene, camera: camera, renderer: renderer }
      };

      /* ---------- الإقلاع ---------- */
      applyResponsiveScale();
      resize();
      setCaption(0);

      buildBottles()
        .then(function () {
          if (loadingRef.current) loadingRef.current.classList.add("hidden");
          canvasEl.classList.add("ready");
          if (bottles.length) {
            if (latinRef.current) latinRef.current.textContent = products[0].latin || "";
            if (arabicRef.current) arabicRef.current.textContent = products[0].arabic || "";
            captionShown = 0;
          }
          startTime = performance.now();
          if (!reduced) raf = window.requestAnimationFrame(frame);
          else {
            applyPhase(0);
            renderer.render(scene, camera);
          }
        })
        .catch(function (err) {
          if (window.console && window.console.error) window.console.error(err);
          if (loadingRef.current) {
            loadingRef.current.textContent = "تعذّر تحميل صور العبوات";
            loadingRef.current.classList.add("stage-failed");
          }
          canvasEl.classList.add("ready");
        });

      return function () {
        if (raf) window.cancelAnimationFrame(raf);
        window.clearTimeout(resizeTimer);
        window.clearTimeout(captionTimer);
        document.removeEventListener("visibilitychange", onVisibility);
        window.removeEventListener("orientationchange", onOrient);
        window.removeEventListener("scroll", sync, true);
        window.removeEventListener("resize", sync);
        if (C.parallax && finePointer) window.removeEventListener("pointermove", onPointerMove);
        if (ro) ro.disconnect();
        else window.removeEventListener("resize", resize);
        if (io) io.disconnect();
        apiRef.current = null;
        scene.traverse(function (obj) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
            mats.forEach(function (m) {
              if (m.map) m.map.dispose();
              m.dispose();
            });
          }
        });
        scene.environment && scene.environment.dispose && scene.environment.dispose();
        disposables.forEach(function (d) {
          if (d && d.dispose) d.dispose();
        });
        renderer.dispose();
      };
    },
    [isActive, items, cfg]
  );

  /* ---------- تفاعل: سحب للتبديل · نقر لفتح تشكيلة العطور ---------- */
  const dragRef = useRef({ x: null, moved: false });

  return (
    <div className="scene-box showcase-media">
      <span className="scene-tag">
        <i /> تشكيلة العطور
      </span>

      <div
        className="perfume-stage"
        ref={wrapRef}
        role="link"
        tabIndex={0}
        title="اسحب لتبديل العطر · انقر لعرض التشكيلة"
        aria-label="عرض العطور"
        onPointerDown={function (e) {
          dragRef.current.x = e.clientX;
          dragRef.current.moved = false;
        }}
        onPointerMove={function (e) {
          if (dragRef.current.x == null) return;
          if (Math.abs(e.clientX - dragRef.current.x) > 10) dragRef.current.moved = true;
        }}
        onPointerUp={function (e) {
          if (dragRef.current.x == null) return;
          const dx = e.clientX - dragRef.current.x;
          dragRef.current.x = null;
          if (Math.abs(dx) > 40) {
            if (apiRef.current) apiRef.current.next();
            return;
          }
          if (!dragRef.current.moved && onPick) onPick();
        }}
        onKeyDown={function (e) {
          if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
            e.preventDefault();
            if (onPick) onPick();
          } else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
            e.preventDefault();
            if (apiRef.current) apiRef.current.next();
          }
        }}
      >
        <div ref={loadingRef} id="stageLoading">
          جارِ التحميل…
        </div>
        <div id="stageCtn">
          <canvas id="stageCanvas" ref={canvasRef} />
        </div>
        {cfg.showCaption ? (
          <div id="captionCtn" ref={captionRef}>
            <div id="captionLatin" ref={latinRef} />
            <div id="captionArabic" ref={arabicRef} />
          </div>
        ) : null}
      </div>
    </div>
  );
}
